<template>
  <el-card><template #header><div class="head"><span>员工管理</span><el-button type="primary" @click="openCreate">新增员工</el-button></div></template>
    <el-table :data="rows" v-loading="loading"><el-table-column prop="name" label="姓名"/><el-table-column prop="account" label="账号"/><el-table-column prop="phone" label="手机号"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.status === 'ENABLED' ? 'success' : 'info'">{{ s.row.status === 'ENABLED' ? '启用' : '禁用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="s"><el-button link @click="openEdit(s.row)">编辑</el-button><el-button link :type="s.row.status === 'ENABLED' ? 'danger' : 'success'" :loading="toggling === s.row.id" @click="toggle(s.row)">{{ s.row.status === 'ENABLED' ? '禁用' : '启用' }}</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无员工"/>
  </el-card>
  <el-dialog v-model="visible" :title="editing ? '编辑员工' : '新增员工'" width="460px" destroy-on-close><el-form label-width="88px"><el-form-item label="姓名" required><el-input v-model.trim="form.name"/></el-form-item><el-form-item label="账号" required><el-input v-model.trim="form.account" :disabled="!!editing"/></el-form-item><el-form-item v-if="!editing" label="初始密码"><el-input v-model="form.password" show-password placeholder="默认 123456"/></el-form-item><el-form-item label="手机号"><el-input v-model.trim="form.phone"/></el-form-item><el-form-item label="角色"><el-select v-model="form.roleId" clearable><el-option v-for="role in roles" :key="role.id" :label="role.name" :value="role.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
</template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import {staffApi,roleApi} from '@/api';const rows=ref<any[]>([]),roles=ref<any[]>([]),loading=ref(false),visible=ref(false),saving=ref(false),editing=ref<any>(null),toggling=ref<number|undefined>();const form=ref<any>({});const unwrap=(r:any)=>r?.data??r;async function load(){loading.value=true;try{const [staffRes,roleRes]:any=await Promise.all([staffApi.list(),roleApi.list()]);const staff=unwrap(staffRes);const role=unwrap(roleRes);rows.value=Array.isArray(staff)?staff:staff?.list??staff?.items??[];roles.value=Array.isArray(role)?role:role?.list??role?.items??[]}catch(e:any){rows.value=[];ElMessage.error(e?.response?.data?.message||e?.message||'员工加载失败')}finally{loading.value=false}}function openCreate(){editing.value=null;form.value={name:'',account:'',password:'',phone:'',roleId:undefined};visible.value=true}function openEdit(r:any){editing.value=r;form.value={name:r.name||'',account:r.account||'',phone:r.phone||'',roleId:r.roleId};visible.value=true}async function save(){if(!form.value.name||!form.value.account)return ElMessage.warning('请填写姓名和账号');saving.value=true;try{if(editing.value)await staffApi.update(editing.value.id,{name:form.value.name,phone:form.value.phone,roleId:form.value.roleId});else await staffApi.create(form.value);ElMessage.success('保存成功');visible.value=false;await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||e?.message||'保存失败')}finally{saving.value=false}}async function toggle(r:any){toggling.value=r.id;try{await staffApi.toggle(r.id,r.status!=='ENABLED');ElMessage.success('状态已更新');await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||e?.message||'状态更新失败')}finally{toggling.value=undefined}}onMounted(load);</script><style scoped>.head{display:flex;align-items:center;justify-content:space-between}</style>
